import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('profetas-menores-miqueas', 'B',
 [dict(t=705, e=745, titulo='Siete capítulos, perfección', txt='Hoy quiero hablarle de los profetas menores, y el que me toca es hablar de Miqueas. Miqueas tiene siete capítulos. Mire qué interesante. ¿Por qué no tiene ocho, que es reinicio? ¿Por qué no tiene tres, la trinidad? ¿Por qué no tiene cuatro, el equilibrio? ¿Por qué no tiene el cinco, que es la gracia? Sino que tiene siete capítulos. Entonces, cuando vemos que tiene siete capítulos, es porque nos está hablando de perfección.'),
  dict(t=1818, e=1862, titulo='El aceite rompe el yugo', txt='«Sucederá en aquel día que la carga de Asiria será quitada de tus hombros, y su yugo de tu cerviz, y el yugo será quebrado a causa de la unción». El aceite, hermano. Usted necesita aceite de la unción para romper el yugo. […] Necesitas el aceite de la unción para que rompan el yugo de esclavitud. Tú ya no eres más esclavo; eres esclavo de Jesucristo.'),
  dict(t=3754, e=3800, titulo='Dios no puede ser burlado', txt='Esto no es un juego, y quiero decirle delante de Dios, al cual yo le sirvo y le tengo temor, que Dios no puede ser burlado. Por eso usted no se quiera pasar de listo con los pecados, probando y probando: «No pasa nada, ni Dios me dice nada». […] Hay gente bien mentirosa. Espero que usted no sea uno de ellos. No mienta. Sea verdadero.')],
 [dict(t=1468, txt='Usted le va a dar cuentas a Dios de lo que hizo con su vida.'),
  dict(t=2405, txt='¿Dios te quiere ver mal? ¿Dios te quiere ver pobre? No, Dios te quiere ver bien.'),
  dict(t=4337, txt='Todo miedo, todo temor fuera hoy, porque el perfecto amor, que es Dios, echa fuera todo temor.')],
 ['Si hoy necesitaras «aceite» para romper un yugo en tu vida, ¿cuál sería ese yugo?',
  '¿En qué área de tu vida has estado «probando» hasta dónde llega la paciencia de Dios?',
  '¿Qué temor quieres entregarle hoy al amor perfecto de Dios?'],
 inicio=461)
